'use strict';const {chromium}=require('playwright'),fs=require('fs'),http=require('http'),path=require('path'),root=path.resolve(__dirname,'..');const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.json':'application/json','.png':'image/png','.jpg':'image/jpeg','.webp':'image/webp'};const app=http.createServer((req,res)=>{const f=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));if(!f.startsWith(root)){res.writeHead(403).end();return}try{let file=f;if(fs.statSync(file).isDirectory())file=path.join(file,'index.html');res.writeHead(200,{'content-type':mime[path.extname(file)]||'application/octet-stream'});fs.createReadStream(file).pipe(res)}catch{res.writeHead(404).end()}});
(async()=>{await new Promise(ok=>app.listen(0,'127.0.0.1',ok));const b=await chromium.launch({headless:true});const results=[];try{for(const width of [320,390,800,1366])for(const lang of ['pt-BR','ar'])for(const route of ['/explore.html','/music.html']){const ctx=await b.newContext({viewport:{width,height:850},reducedMotion:'reduce'});await ctx.addInitScript(v=>localStorage.setItem('match_lang',v),lang);const p=await ctx.newPage();await p.route(/google-analytics|googletagmanager|googlesyndication|doubleclick/i,r=>r.abort());await p.goto('http://127.0.0.1:'+app.address().port+route,{waitUntil:'domcontentloaded',timeout:30000});await p.locator('#ma-ambient-jonas .ja-bubble').waitFor({state:'visible',timeout:18000});await p.waitForTimeout(220);const v=await p.evaluate(()=>{const sels=['.hub-links a','.hub-brand','.hub-links','#lang-switcher'],bubble=document.querySelector('#ma-ambient-jonas .ja-bubble'),br=bubble.getBoundingClientRect();const obs=[];for(const sel of sels)for(const el of document.querySelectorAll(sel)){const r=el.getBoundingClientRect();if(!r.width||!r.height||getComputedStyle(el).display==='none')continue;const w=Math.max(0,Math.min(br.right,r.right)-Math.max(br.left,r.left)),h=Math.max(0,Math.min(br.bottom,r.bottom)-Math.max(br.top,r.top));if(w*h>64)obs.push({selector:sel,text:el.textContent?.trim().slice(0,45),area:Math.round(w*h),rect:{x:r.x,y:r.y,w:r.width,h:r.height}})}return {lang:document.documentElement.lang,dir:document.documentElement.dir,overflow:document.documentElement.scrollWidth-innerWidth,bubble:{x:br.x,y:br.y,w:br.width,h:br.height},overlaps:obs}});results.push({route,width,locale:lang,...v});console.log(route,width,lang,'overlaps',v.overlaps.length,'overflow',v.overflow);if(v.overlaps.length)throw Error('Jonas obscures '+JSON.stringify({route,width,lang,overlaps:v.overlaps}));if(v.overflow>3)throw Error('horizontal overflow '+route+' '+width);await ctx.close()}}finally{fs.writeFileSync(path.join(root,'docs/design-reviews/20261014/ambient-overlap-audit.json'),JSON.stringify({results},null,2));await b.close();app.close()}console.log('PASS '+results.length+' ambient/navigation visibility combinations')})().catch(e=>{console.error(e.stack);process.exitCode=1});
